mapper.select:
SELECT
    ma.id,
    ma.title,
    ma.applicant_id,
    u1.real_name AS applicant_name,
    ma.maintainer_id,
    u2.real_name AS maintainer_name,
    ma.dept_id,
    d.name AS dept_name,
    ma.workflow_id,
    ma.status,
    ma.guarantee_declaration,
    ma.create_time,
    ma.update_time,
    (SELECT COUNT(*) FROM asset a WHERE a.application_id = ma.id AND COALESCE(a.deleted, 0) = 0) AS asset_count
FROM material_application ma
LEFT JOIN sys_user u1 ON ma.applicant_id = u1.id AND COALESCE(u1.deleted, 0) = 0
LEFT JOIN sys_user u2 ON ma.maintainer_id = u2.id AND COALESCE(u2.deleted, 0) = 0
LEFT JOIN sys_dept d ON ma.dept_id = d.id AND COALESCE(d.deleted, 0) = 0

    AND ma.id = #{id}
    AND ma.applicant_id = #{applicantId}
    AND ma.maintainer_id = #{maintainerId}
    AND ma.dept_id = #{deptId}
    AND ma.workflow_id = #{workflowId}
    AND ma.status = #{status}
    AND ma.deleted = #{deleted}
    AND COALESCE(ma.deleted, 0) = 0



        AND ma.applicant_id IN

            #{applicantId}




    ORDER BY ${orderByField}

        ${orderByDirection}



    LIMIT #{offset}, #{limit}
